#!/usr/bin/env node
/* Generates everything that is derived from design/tokens.json and design/icons/ (so values live in exactly one place):
 *   design/README.md          token tables, accent palette, icon gallery (generated, do not edit by hand)
 *   src/core/accent.js        region gen:palette  (PALETTE of the accent colours)
 *   src/ui/icons.js           region gen:icons    (COLS: sprite column per icon name)
 *
 *   node tools/design_doc.js --write   regenerate (npm run spec does this too, together with the product spec)
 *   node tools/design_doc.js           check only: exits 1 and names the stale files (tests/design.test.js does the same,
 *                                      so `npm test` fails while generated files are out of date)
 *
 * For other generators: tools/spec_gen.js fills the <!-- gen:tokens --> / <!-- gen:icons --> blocks of public/docs/SPEC.md with
 * tokensMarkdown({ level: 0, bare: true }) and iconsMarkdown({ previews: false, bare: true }) (level 0 = bold titles instead of
 * headings; bare = without the "generated by" line; no image previews, the same text works in the private and the public tree). */
'use strict';
var fs = require('fs'), path = require('path'), T = require('./tokens.js');
var ROOT = path.join(__dirname, '..');
var GEN = 'generated by tools/design_doc.js from design/tokens.json – do not edit by hand, run: node tools/design_doc.js --write';

/* LF line ends whatever the checkout uses (Windows core.autocrlf), so the check is the same on every OS */
function lfRead(p) { return fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n'); }
function code(s) { return '`' + String(s).replace(/`/g, '\\`') + '`'; }
function cell(s) { return String(s).replace(/\|/g, '\\|').replace(/\n/g, ' '); }
function heading(level, text) { return level ? new Array(level + 1).join('#') + ' ' + text : '**' + text + '**'; }

/* token tables (all groups, in file order) */
function tokensMarkdown(opt) {
  var t = T.load(), lv = opt && opt.level !== undefined ? opt.level : 2, out = [];
  if (!(opt && opt.bare)) out.push('<!-- ' + GEN + ' -->', '');
  out.push('Placeholder in CSS: `@<group>.<name>@` (replaced at build time by tools/build.js). Accent colours are written as `@accent@`.', '');
  out.push('**Scaling:** ' + t.scaling, '');
  Object.keys(t.groups).forEach(function (g) {
    var G = t.groups[g];
    out.push(heading(lv, G.title + (G.css === false ? '' : ' (' + code('@' + g + '.…@') + ')')), '', G.description, '');
    out.push('| Token | Value | Use |', '|---|---|---|');
    Object.keys(G.tokens).forEach(function (n) {
      var name = G.css === false ? code(n) : code('@' + g + '.' + n + '@');
      out.push('| ' + name + ' | ' + code(G.tokens[n].value) + ' | ' + cell(G.tokens[n].description) + ' |');
    });
    out.push('');
  });
  var ic = t.icons, m = T.map(t);
  out.push(heading(lv, 'Icon sprite (' + code('@ic.…@') + ')'), '', ic.description, '');
  out.push('| Token | Value | Use |', '|---|---|---|');
  out.push('| ' + code('@ic.cell@') + ' | ' + code(m['ic.cell']) + ' | Size of one sprite cell (width and height of `.ic`) |');
  ic.rows.forEach(function (r, i) {
    out.push('| ' + code('@ic.row.' + r + '@') + ' | ' + code(m['ic.row.' + r]) + ' | `background-position-y` of row ' + i + ': icon drawn in colour ' + code('@c.' + r + '@') + ' |');
  });
  out.push('');
  return out.join('\n');
}

/* icon list with previews (paths relative to design/) */
function iconsMarkdown(opt) {
  var rel = (opt && opt.iconPath) || 'icons/', pre = !(opt && opt.previews === false), list = T.order(), cellPx = T.load().icons.cell;
  var out = (opt && opt.bare ? [] : ['<!-- ' + GEN + ' -->', '']).concat(['Sources: `design/icons/<name>.svg`. Column order: `design/icons/order.json` (append only). ' +
    'In code: `N.ui.icon(parent, \'<name>\', state)` (src/ui/icons.js).', '',
    pre ? '| Column | Name | Preview | x offset |' : '| Column | Name | x offset |', pre ? '|---|---|---|---|' : '|---|---|---|']);
  list.forEach(function (n, i) {
    out.push('| ' + i + ' | ' + code(n) + ' | ' + (pre ? '<img src="' + rel + n + '.svg" width="28" height="28" alt="' + n + '"> | ' : '') + code(i ? -(i * cellPx) + 'px' : '0') + ' |');
  });
  out.push('');
  return out.join('\n');
}

function readme() {
  return [
    '# Design system',
    '',
    '<!-- ' + GEN + ' -->',
    '',
    'All important design values of the app – colours, type scale, spacing, radii, focus, motion, layers and layout constants – ' +
    'are stored once in [`tokens.json`](tokens.json); every icon is one SVG file in [`icons/`](icons/). Everything else is ' +
    'generated from these two places, so a value is changed in one spot and the change reaches every screen. The files are ' +
    'plain JSON and SVG on purpose: a port to another TV platform can read them directly.',
    '',
    '## How to change something',
    '',
    '1. Edit the value (and its description) in `design/tokens.json`, or an icon in `design/icons/<name>.svg`.',
    '2. Run `npm run spec` – regenerates this page, the accent palette in `src/core/accent.js`, the icon columns in `src/ui/icons.js` and the token and icon tables of the product spec `SPEC.md` (`node tools/design_doc.js --write` does only the design files).',
    '3. Colours used in images (icon rows, background, pointer outline, QR code) or a changed icon: run `node tools/make_assets.js` (needs `rsvg-convert`).',
    '4. Run `npm test`. The build replaces the placeholders in `src/css/app.css` with the values.',
    '',
    'New icon: add `design/icons/<name>.svg` (28 × 28 view box, `currentColor` for stroke/fill, same `<g>` wrapper as the others), append the name to `design/icons/order.json`, then steps 2–4.',
    '',
    '## What is enforced',
    '',
    '- The build fails on any colour literal (`#hex`, `rgb()`/`rgba()`, `hsl()`, colour names) in `src/css/*.css` – every colour is a token. `node tools/tokenize_css.js --write` converts new literals that already have a token and lists the ones that still need one.',
    '- The build fails on any placeholder that does not resolve (typo or deleted token).',
    '- `npm test` fails when this page, the token/icon blocks of the product spec, `src/core/accent.js`, `src/ui/icons.js`, `src/assets/icons.svg`/`icons.json` are out of date, when an icon in `src/ui/icons.js` has no SVG or an SVG is not in the sprite, when a token is used nowhere (not in `src/css`, not as icon row colour, not via `T.color()` in `tools/`; an intentionally free step of a scale is marked `"reserved": true`), and when a brand-specific accent colour appears in `tokens.json` (it belongs only in `brand/<id>.json`).',
    '- Values that are one-off geometry (positions, sizes of single elements, circles) stay as plain px in the CSS.',
    '',
    tokensMarkdown({ level: 2 }).replace(/^<!--[^\n]*-->\n\n/, ''),
    '## Icons',
    '',
    iconsMarkdown().replace(/^<!--[^\n]*-->\n\n/, '')
  ].join('\n');
}

/* region in a JS file: "/* gen:<id> … *\/" line … "/* /gen:<id> *\/" line; content = lines in between */
function jsRegion(text, id, body, file) {
  var re = new RegExp('(\\n[ \\t]*/\\* gen:' + id + '\\b[^\\n]*\\*/\\n)([\\s\\S]*?)(\\n[ \\t]*/\\* /gen:' + id + ' \\*/)');
  if (!re.test(text)) throw new Error(file + ': region gen:' + id + ' missing');
  return text.replace(re, function (all, a, old, b) { return a + body + b; });
}
function paletteJs() {
  var p = T.palette(), lines = [], row = [];
  p.forEach(function (x, i) { row.push("['" + x.id + "', '" + x.color + "']"); if (row.length === 4 || i === p.length - 1) { lines.push(row.join(', ')); row = []; } });
  return '  var PALETTE = [\n    ' + lines.join(',\n    ') + '\n  ];';
}
function iconsJs() {
  return '  var COLS = { ' + T.order().map(function (n, i) { return n + ': ' + i; }).join(', ') + ' };';
}
/* [{ file, want }] – every generated file with its expected content */
function outputs() {
  var o = [], rd = function (f) { return lfRead(path.join(ROOT, f)); };
  o.push({ file: 'design/README.md', want: readme() });
  o.push({ file: 'src/core/accent.js', want: jsRegion(rd('src/core/accent.js'), 'palette', paletteJs(), 'src/core/accent.js') });
  o.push({ file: 'src/ui/icons.js', want: jsRegion(rd('src/ui/icons.js'), 'icons', iconsJs(), 'src/ui/icons.js') });
  return o;
}
function stale() {
  return outputs().filter(function (x) {
    var p = path.join(ROOT, x.file);
    return !fs.existsSync(p) || lfRead(p) !== x.want;
  }).map(function (x) { return x.file; });
}
function write() {
  var w = [];
  outputs().forEach(function (x) {
    var p = path.join(ROOT, x.file);
    if (!fs.existsSync(p) || lfRead(p) !== x.want) { fs.writeFileSync(p, x.want); w.push(x.file); }
  });
  return w;
}

if (require.main === module) {
  if (process.argv.indexOf('--write') >= 0) {
    var w = write();
    console.log(w.length ? 'updated: ' + w.join(', ') : 'all generated design files are up to date');
  } else {
    var s = stale();
    if (s.length) { console.error('stale (run node tools/design_doc.js --write): ' + s.join(', ')); process.exit(1); }
    console.log('all generated design files are up to date');
  }
}
module.exports = { tokensMarkdown: tokensMarkdown, iconsMarkdown: iconsMarkdown, readme: readme, outputs: outputs, stale: stale, write: write };
